        private static string LowerStrides() => "\u0001\u0001\u0001\u0002\u0002\u0002\u0002\u0001\u0002\u0001\u0002\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0002\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0002\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0002\u0002\u0001\u0002\u0001\u0001\u0002\u0001\u0002\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0002\u0002\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0002\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0002\u0002\u0001\u0002\u0002\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0002\u0001\u0002\u0001\u0001\u0001\u0001\u0001\u0002\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0002\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0002\u0002\u0001\u0002\u0002\u0002\u0002\u0002\u0001\u0002\u0001\u0001\u0002\u0002\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0001\u0002\u0001\u0001\u0001\u0002\u0001\u0001\u0001\u0002\u0001\u0001\u0001";

        public static int ToUpperSupplementary(int point)
        {
            if (point >= 0x10428 && point <= 0x1044F)
            {
                return point + -40;
            }

            if (point >= 0x104D8 && point <= 0x104FB)
            {
